import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import java.time.Duration;

public class OuterPackingTest {
    public static void main(String[] args) {
        WebDriver driver = new ChromeDriver();
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(10));
        try {
            driver.get("https://gc-dev.centralindia.cloudapp.azure.com/ambica/master/outer-packing");
            driver.findElement(By.xpath("//button[contains(text(),'ADD Outer Packing')]")).click();
            driver.findElement(By.id("outerPacking")).sendKeys("Selenium Packing Box");
            driver.findElement(By.xpath("//button[contains(text(),'Submit')]")).click();
            driver.findElement(By.xpath("//input[@placeholder='Search by Outer Packing']")).sendKeys("Selenium Packing Box");
            driver.findElement(By.xpath("//button[contains(text(),'Reset')]")).click();
        } finally {
            driver.quit();
        }
    }
}
